txt='\n'.join(P)
txt='\n'.join(x if x.startswith('### ') else re.sub(r'(?<=[a-z)])(\d{1,2})(?=[\s,.])','',x) for x in txt.split('\n'))
txt=re.sub(r'(\d),(\d)',r'\1.\2',txt)   # decimal commas
txt=re.sub(r'\bRQ(\d)\.(\d)\s?',r'research question \1 point \2 ',txt)
for a,b in [(r'\bHOEs\b','H O Es'),(r'\bHOE\b','H O E'),(r'\bOS\b','O S'),(r'\bESE\b','E S E'),(r'\bDSR\b','D S R'),(r'\bSE\b','S E'),(r'\bEMSE\b','E M S E'),(r'\bIST\b','I S T'),(r'\bJSS\b','J S S'),(r'\bTSE\b','T S E'),(r'\bWoS\b','Web of Science'),(r'\bOSF\b','O S F'),(r'\bSSRN\b','S S R N'),(r'\bNASEM\b','N A S E M'),(r'\bUNESCO\b','UNESCO'),(r'\bCERN\b','CERN'),(r'\bRE\b','R E'),(r'\bUML\b','U M L'),(r'\bBPMN\b','B P M N')]:
    txt=re.sub(a,b,txt)
txt=re.sub(r'\bFigs?\. ','Figure ',txt); txt=re.sub(r'\((\d+)\/(\d+)\)',r'(\1 out of \2)',txt); txt=txt.replace(' & ',' and '); txt=re.sub(r'\((i{1,3}|iv|v|vi)\) ',lambda m:{'i':'first, ','ii':'second, ','iii':'third, ','iv':'fourth, ','v':'fifth, ','vi':'sixth, '}[m.group(1)],txt); txt=clean(txt)
